// Process Checker response and decide next step
const setupData = $node['Setup Sections'].json;
const makerContent = $node['AI Maker'].json.response;
const checkerResponse = $input.first().json.response;

console.log(`Processing Checker response for section: ${setupData.current_section.name}`);

// Parse checker response
let checkerData;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback if no JSON found
    checkerData = {
      approved: true,
      feedback: "Content appears acceptable",
      quality_score: 7
    };
  }
} catch (error) {
  console.log(`Checker JSON parsing failed: ${error.message}`);
  checkerData = {
    approved: true,
    feedback: "Content appears acceptable",
    quality_score: 7
  };
}

console.log(`Checker result: ${checkerData.approved ? 'APPROVED' : 'REJECTED'} (Score: ${checkerData.quality_score})`);

// Return data for next step
return {
  json: {
    ...setupData,
    maker_content: makerContent,
    checker_approved: checkerData.approved,
    checker_feedback: checkerData.feedback,
    checker_score: checkerData.quality_score
  }
};

